#!/usr/bin/env node
/**
 * split-bundle.mjs — data/derived/es-fiscal-bundle.json  ->  src/data/generated/*.json
 *
 * The bundle is the single source of truth. This script only *partitions* it, so each
 * route loads its own section and Next code-splits on the boundary. It performs no
 * arithmetic, no rounding, no filling and no defaulting: every value written is the
 * value read. Missing keys are a hard failure, never a silent `{}`.
 *
 * Output is gitignored and regenerated by `prebuild` (after `data:verify`), so a bundle
 * that fails a tie-out cannot produce a build.
 *
 * Run: node scripts/split-bundle.mjs
 */
import { readFileSync, writeFileSync, mkdirSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const BUNDLE = join(ROOT, "data", "derived", "es-fiscal-bundle.json");
const OUT_DIR = join(ROOT, "src", "data", "generated");

const fail = (msg) => {
  console.error(`split-bundle: ${msg}`);
  process.exit(1);
};

let raw;
try {
  raw = readFileSync(BUNDLE, "utf8");
} catch (err) {
  fail(`cannot read bundle at ${BUNDLE} — ${err.message}`);
}

let B;
try {
  B = JSON.parse(raw);
} catch (err) {
  fail(`bundle is not valid JSON — ${err.message}`);
}

/* ---------------------------------------------------------------- key contract --
 * Every key this app depends on, grouped by the file it lands in. A key that
 * disappears upstream must break the build here, loudly, rather than surface as an
 * empty panel in the console. */
const SECTION_KEYS = {
  map: ["W", "H", "CB", "regions"],
  revenue: [
    "revYears", "revTaxes", "revNational", "gg", "natRev", "PARTS", "natParts",
    "natSub", "subLab", "subSrc", "mapAgg", "coverage", "euNote", "national2",
    "foralCoverage", "salesDetail",
  ],
  /* The economic-transaction split (`econ*`) travels with spending: the only screen
   * that renders it is the spending dossier's "what it is spent on" block. */
  spending: [
    "spendYears", "spendNational", "spendBySector", "divisions", "divES", "divEN",
    "spendSub", "spendSubES", "spendSubEN", "spendNoteES", "spendNoteEN", "spendAgg",
    "econKeys", "econES", "econEN", "spendTerr", "localAreas",
  ],
  who: ["who", "irpfScale", "madridScale"],
  debt: ["debt"],
};

const missing = [];
for (const [section, keys] of Object.entries(SECTION_KEYS)) {
  for (const k of keys) {
    if (!(k in B)) missing.push(`${k} (needed by ${section}.json)`);
  }
}
if (missing.length) {
  fail(`bundle is missing ${missing.length} expected key(s):\n  - ${missing.join("\n  - ")}`);
}

/* Region records carry three sections' worth of data on one object. The geometry
 * stays in map.json; the numbers travel with the mode that renders them. */
const GEOM_FIELDS = ["id", "nuts", "es", "en", "d", "cx", "cy", "bbox", "inset", "foral"];
/* `macro` (GDP and population by year) travels with both modes: each divides its
 * own figures by it. */
const REV_FIELDS = ["rev", "rev2", "parts", "macro"];
const SPEND_FIELDS = ["spend", "econ", "local", "macro"];

if (!Array.isArray(B.regions) || B.regions.length === 0) {
  fail("bundle.regions is not a non-empty array");
}
for (const r of B.regions) {
  for (const f of [...GEOM_FIELDS, ...REV_FIELDS, ...SPEND_FIELDS]) {
    if (!(f in r)) fail(`region ${r.id ?? "?"} is missing field "${f}"`);
  }
}

const pick = (obj, fields) => Object.fromEntries(fields.map((f) => [f, obj[f]]));

const mapJson = {
  W: B.W,
  H: B.H,
  CB: B.CB,
  regions: B.regions.map((r) => pick(r, GEOM_FIELDS)),
};

const byRegion = (fields) =>
  Object.fromEntries(B.regions.map((r) => [r.id, pick(r, fields)]));

const revenueJson = {
  ...pick(B, SECTION_KEYS.revenue),
  regions: byRegion(REV_FIELDS),
};

const spendingJson = {
  ...pick(B, SECTION_KEYS.spending),
  regions: byRegion(SPEND_FIELDS),
};

const whoJson = pick(B, SECTION_KEYS.who);
const debtJson = pick(B, SECTION_KEYS.debt);

/* Sorted year lists, so a page can name "the latest year" without scanning object
 * keys at render time. These are the bundle's own keys, ordered — not derived data.
 * `gg` is duplicated here (it also lives in revenue.json, its home section) because
 * the spending headline reads gg.exp and must not pull the whole revenue section in. */
const yearsOf = (obj) => Object.keys(obj).sort();

const metaJson = {
  generatedAt: new Date().toISOString(),
  bundlePath: "data/derived/es-fiscal-bundle.json",
  bundleBytes: statSync(BUNDLE).size,
  years: {
    rev: B.revYears,
    spend: B.spendYears,
    gg: yearsOf(B.gg),
    debt: B.debt.years,
  },
  debtRef: B.debt.ref,
  gg: B.gg,
};

mkdirSync(OUT_DIR, { recursive: true });

const files = {
  "map.json": mapJson,
  "revenue.json": revenueJson,
  "spending.json": spendingJson,
  "who.json": whoJson,
  "debt.json": debtJson,
  "meta.json": metaJson,
};

for (const [name, data] of Object.entries(files)) {
  const text = JSON.stringify(data);
  writeFileSync(join(OUT_DIR, name), text);
  console.log(`  ${name.padEnd(14)} ${String(text.length).padStart(8)} bytes`);
}

console.log(
  `split-bundle: ${Object.keys(files).length} files from ${metaJson.bundleBytes} bytes of bundle -> src/data/generated/`,
);
